function loadtable(){$("#tablesystemusers").DataTable({processing:!0,serverSide:!0,filter:!0,responsive:!0,destroy:!0,ajax:{url:"/Home/SystemUserz",type:"POST",datatype:"json"},columnDefs:[{visible:!0,searchable:!0}],columns:[{data:"id",render:function(n,t,i,r){return r.row+r.settings._iDisplayStart+1}},{data:"fullname",autoWidth:!0},{data:"userName",autoWidth:!0},{data:"active",render:function(n){return n==!0?(classfa="bi-unlock",classbtn="Deactivate",n):(classfa="bi-lock",classbtn="Activate",n)}},{data:"position",autoWidth:!0},{data:null,render:function(n){return`
                    <div class="dropdown">
                      <button class="btn btn-light btn-sm" type="button" data-bs-toggle="dropdown" aria-expanded="false">
                        <i class="bi bi-three-dots-vertical"></i>
                      </button>
                      <ul class="dropdown-menu">
                        <li><a class="dropdown-item" href="/Admin/System-User/Upsert?id=${n.id}"><i class="bi bi-pencil-square me-2"></i> Edit</a></li>
                        <li><a class="dropdown-item" href="/Account/ChangeUserPassword?id=${n.id}&url=/Admin/System-User/Index"><i class="bi bi-arrow-clockwise me-2"></i> Change Password</a></li>
                        <li><a class="dropdown-item" onclick=Systemusermanger("/api/LockUnlockAccount?id=${n.id}") href="#"><i class="bi ${classfa} me-2"></i> ${classbtn}</a></li>
                        <li><a class="dropdown-item" onclick=DeleteSystemUser("/api/ManageSystemUser?id=${n.id}") href="#"><i class="bi bi-trash3 me-2"></i> Delete</a></li>
                      </ul>
                    </div>
                    `}}]})}function DeleteSystemUser(n){const t=Swal.mixin({customClass:{confirmButton:"btn btn-success",cancelButton:"btn btn-danger me-2"},buttonsStyling:!1});t.fire({title:"Are you sure?",text:"You won't be able to recover this!",icon:"warning",showCancelButton:!0,confirmButtonText:"Yes, delete it!",cancelButtonText:"No, cancel!",reverseButtons:!0}).then(t=>{t.isConfirmed?$.ajax({type:"DELETE",url:n,success:function(n){$.unblockUI();n.success?(swal.fire("Deleted!",n.message,"success"),loadtable()):swal.fire("Deleted!",n.message,"error")},beforeSend:function(){blockcallback()},error:function(){$.unblockUI();Swal.fire({icon:"error",title:"Oops...",text:"Something went wrong!",footer:"Check internet connectivity!"})},complete:function(){$.unblockUI()}}):t.dismiss===Swal.DismissReason.cancel&&swal.fire("Cancelled","System User Account NOT Deleted!","error")})}function Systemusermanger(n){const t=Swal.mixin({customClass:{confirmButton:"btn btn-success",cancelButton:"btn btn-danger me-2"},buttonsStyling:!1});t.fire({title:"Are you sure?",text:"You want to carry out this action?",icon:"warning",showCancelButton:!0,confirmButtonText:"Yes, Execute!",cancelButtonText:"No, cancel!",reverseButtons:!0}).then(t=>{t.isConfirmed?$.ajax({type:"POST",url:n,success:function(n){$.unblockUI();n.success?(swal.fire("Action Message!",n.message,"success"),loadtable()):swal.fire("Action Message!",n.message,"error")},beforeSend:function(){blockcallback()},error:function(){$.unblockUI();Swal.fire({icon:"error",title:"Oops...",text:"Something went wrong!",footer:"Check internet connectivity!"})},complete:function(){$.unblockUI()}}):t.dismiss===Swal.DismissReason.cancel&&swal.fire("Cancelled","Action aborted!","error")})}function blockcallback(){$.blockUI({message:'<div class="bs-spinner mt-4 mt-lg-0"><div class= "spinner-border text-success mr-2 mt-2" style="width: 10rem; height: 10rem;" role="status"><span class="sr-only">Loading...<\/span><\/div>',fadeIn:800,overlayCSS:{backgroundColor:"#1b2024",opacity:.8,zIndex:1200,cursor:"wait"},css:{border:0,color:"#fff",zIndex:1201,padding:0,backgroundColor:"transparent"},onBlock:function(){}})}var classbtn="",classfa="",ap="";$(document).ready(function(){loadtable()});